554	            assertEquals(n - 1, replayCount);
555	            assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM no_fly_zone", Integer.class));
556	            assertEquals(1, jdbc.queryForObject(
557	                    "SELECT COUNT(*) FROM request_dedup WHERE request_id = ?", Integer.class, requestId));
558	            // 同键异参事后仍 409
